#!/usr/bin/env bash
set -euo pipefail
set +H
TS="$(date +%Y%m%d_%H%M%S)"
LIVE="/var/www/ndsp-my"
PREMIUM="$LIVE/_premium"
ASSETS="$PREMIUM/assets"
DATA="$PREMIUM/data"
REAL_USER="${SUDO_USER:-$USER}"
REAL_HOME="$(getent passwd "$REAL_USER" | cut -d: -f6 || echo "$HOME")"
REPORT="$REAL_HOME/ndsp_launch_reports/NDSP_V500_PREMIUM_BOOTSTRAP_$TS.md"
BACKUP="$REAL_HOME/ndsp_launch_backups/ndsp-v500-premium-bootstrap-$TS"
CHECKPOINT="$REAL_HOME/ndsp_release_checkpoints/NDSP_V500_PREMIUM_BOOTSTRAP_$TS"
mkdir -p "$REAL_HOME/ndsp_launch_reports" "$REAL_HOME/ndsp_launch_backups" "$REAL_HOME/ndsp_release_checkpoints"
log(){ echo "$*" | tee -a "$REPORT"; }
log "REPORT=$REPORT"
log "TS=$TS"
log "LIVE=$LIVE"
log "PREMIUM=$PREMIUM"
[ -d "$LIVE" ] || { log "ERROR=LIVE_NOT_FOUND"; exit 1; }
mkdir -p "$BACKUP" "$CHECKPOINT"
if [ -d "$PREMIUM" ]; then cp -a "$PREMIUM" "$BACKUP/_premium.before_v500"; log "BACKUP=$BACKUP/_premium.before_v500"; else log "BACKUP=NO_PREVIOUS_PREMIUM"; fi
rm -rf "$PREMIUM"
mkdir -p "$ASSETS" "$DATA"
cat > "$DATA/assets.json" <<'JSON'
{"markets":[{"id":"CRYPTO","ar":"العملات الرقمية","en":"Crypto","assets":[["BTCUSDT","بيتكوين","Bitcoin"],["ETHUSDT","إيثريوم","Ethereum"],["SOLUSDT","سولانا","Solana"]]},{"id":"FX","ar":"العملات","en":"FX","assets":[["EURUSD","اليورو / الدولار","Euro / US Dollar"],["GBPUSD","الإسترليني / الدولار","Pound / US Dollar"],["USDJPY","الدولار / الين","US Dollar / Yen"]]},{"id":"METALS_ENERGY","ar":"المعادن والطاقة","en":"Metals & Energy","assets":[["XAUUSD","الذهب","Gold"],["XAGUSD","الفضة","Silver"],["USOIL","النفط الأمريكي","WTI Crude Oil"],["UKOIL","برنت","Brent"]]},{"id":"COMMODITIES","ar":"السلع","en":"Commodities","assets":[["COPPER","النحاس","Copper"],["NATGAS","الغاز الطبيعي","Natural Gas"],["CORN","الذرة","Corn"],["WHEAT","القمح","Wheat"],["SOYBEAN","فول الصويا","Soybean"],["COFFEE","القهوة","Coffee"],["SUGAR","السكر","Sugar"],["COCOA","الكاكاو","Cocoa"],["COTTON","القطن","Cotton"]]},{"id":"INDICES_MACRO","ar":"المؤشرات والماكرو","en":"Indices & Macro","assets":[["SPX","ستاندرد آند بورز","S&P 500"],["NDX","ناسداك 100","Nasdaq 100"],["DXY","مؤشر الدولار","US Dollar Index"]]}]}
JSON
cat > "$ASSETS/premium.css" <<'CSS'
:root{--bg:#030304;--ink:#f7f1e2;--muted:#aca28e;--panel:#0b0c10;--panel2:#14161d;--gold:#d7b652;--gold2:#f2d46b;--line:rgba(215,182,82,.25);--green:#86efac;--yellow:#fde68a;--red:#fca5a5}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#030304;color:var(--ink);font-family:Tajawal,system-ui,-apple-system,"Segoe UI",sans-serif}body{direction:rtl;background:radial-gradient(circle at 50% -10%,rgba(242,212,107,.21),transparent 33%),radial-gradient(circle at 0% 25%,rgba(215,182,82,.08),transparent 25%),linear-gradient(180deg,#050506,#000);padding-bottom:70px}a{color:inherit;text-decoration:none}.shell{width:min(1160px,calc(100% - 30px));margin:auto}.top{position:sticky;top:0;z-index:40;background:rgba(3,3,4,.9);border-bottom:1px solid var(--line);backdrop-filter:blur(16px)}.topin{display:flex;gap:14px;align-items:center;justify-content:space-between;padding:14px 0}.brand{display:flex;gap:12px;align-items:center;font-weight:950}.logo{width:44px;height:44px;border-radius:16px;background:linear-gradient(135deg,var(--gold2),var(--gold));display:grid;place-items:center;color:#050505;box-shadow:0 18px 42px rgba(215,182,82,.16)}.brand small{display:block;color:var(--muted);font-size:12px}.nav{display:flex;gap:8px;flex-wrap:wrap}.nav a{padding:9px 12px;border-radius:999px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);font-size:13px;font-weight:850;color:#dad2c1}.nav a.on{color:var(--gold2);border-color:var(--line);background:rgba(215,182,82,.08)}.lang button{border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.04);color:var(--muted);border-radius:999px;padding:8px 10px;font-weight:900}.lang button.on{background:var(--gold2);color:#050505}.hero{padding:52px 0 22px}.kicker{display:flex;gap:10px;flex-wrap:wrap;align-items:center;color:var(--gold2);font-weight:950;margin-bottom:14px}.dot{width:9px;height:9px;background:var(--green);border-radius:50%;box-shadow:0 0 0 7px rgba(134,239,172,.1)}h1{font-size:clamp(44px,8vw,84px);line-height:1.03;margin:0 0 14px;font-weight:950;letter-spacing:-1.1px}.hero p{font-size:clamp(17px,3vw,22px);line-height:1.85;color:var(--muted);max-width:900px;margin:0}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}.btn{min-height:52px;border:0;border-radius:18px;padding:0 18px;background:linear-gradient(135deg,var(--gold2),var(--gold));color:#050505;font-weight:950;display:inline-flex;align-items:center;justify-content:center}.btn.secondary{background:rgba(255,255,255,.045);color:var(--ink);border:1px solid rgba(255,255,255,.1)}.pill{display:inline-flex;align-items:center;border:1px solid var(--line);background:rgba(215,182,82,.08);color:var(--gold2);border-radius:999px;padding:8px 12px;font-size:13px;font-weight:950}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px;margin:18px 0}.card{grid-column:span 12;border:1px solid var(--line);background:linear-gradient(145deg,rgba(255,255,255,.06),rgba(255,255,255,.018)),linear-gradient(180deg,var(--panel2),var(--panel));border-radius:30px;padding:24px;box-shadow:0 30px 90px rgba(0,0,0,.45);overflow:hidden}.card h2,.card h3{margin:0 0 12px;color:var(--gold2)}.card p{color:var(--muted);line-height:1.8}.span8{grid-column:span 8}.span6{grid-column:span 6}.span4{grid-column:span 4}.span3{grid-column:span 3}.value{font-size:clamp(28px,5vw,46px);font-weight:950;color:white;line-height:1.08}.label{color:var(--muted);font-size:13px;font-weight:900;margin-bottom:8px}.chip{display:inline-flex;width:max-content;border-radius:999px;padding:8px 12px;font-weight:950;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.04)}.ok{color:var(--green);border-color:rgba(134,239,172,.25)}.warn{color:var(--yellow);border-color:rgba(253,230,138,.25)}.bad{color:var(--red);border-color:rgba(252,165,165,.25)}.market{margin:16px 0}.market h2{color:white}.assets{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.asset{min-height:128px;border:1px solid rgba(255,255,255,.09);border-radius:24px;background:radial-gradient(circle at 20% 0%,rgba(215,182,82,.14),transparent 44%),rgba(255,255,255,.035);color:var(--ink);padding:18px;text-align:start}.asset b{display:block;color:var(--gold2);font-size:25px}.asset span{display:block;color:white;font-weight:900;margin-top:6px}.asset small{display:block;color:var(--muted);line-height:1.55;margin-top:8px}.radar{width:min(520px,100%);aspect-ratio:1;border-radius:50%;border:1px solid var(--line);margin:auto;position:relative;overflow:hidden;background:radial-gradient(circle,rgba(215,182,82,.13),rgba(255,255,255,.035) 43%,rgba(5,5,7,.9) 72%);box-shadow:inset 0 0 80px rgba(0,0,0,.55),0 30px 90px rgba(0,0,0,.45)}.radar:before,.radar:after{content:"";position:absolute;inset:10%;border:1px solid rgba(215,182,82,.18);border-radius:50%}.radar:after{inset:27%}.sweep{position:absolute;inset:-1px;background:conic-gradient(from 0deg,rgba(242,212,107,.36),rgba(242,212,107,.06) 17%,transparent 43%);animation:spin 8s linear infinite}.core{position:absolute;inset:34%;border-radius:50%;display:grid;place-items:center;text-align:center;background:#07080a;border:1px solid var(--line)}.core b{color:var(--gold2);font-size:28px}.core span{display:block;color:var(--muted);font-size:12px;margin-top:6px}@keyframes spin{to{transform:rotate(360deg)}}.metric{border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.035);border-radius:20px;padding:14px;margin-bottom:10px}.mrow{display:grid;grid-template-columns:150px 1fr 45px;gap:12px;align-items:center}.bar{height:11px;border-radius:99px;background:rgba(255,255,255,.08);overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,#8d7430,var(--gold2));border-radius:99px}.note{border-top:1px solid rgba(255,255,255,.08);margin-top:14px;padding-top:14px;color:var(--muted)!important}.footer{text-align:center;color:#746b5e;line-height:1.8;padding:30px 0}@media(max-width:900px){.top{position:relative}.topin{align-items:flex-start;flex-direction:column}.span8,.span6,.span4,.span3{grid-column:span 12}.assets{grid-template-columns:1fr}.card{border-radius:24px;padding:18px}.mrow{grid-template-columns:1fr;gap:8px}.core{inset:31%}}
CSS
cat > "$ASSETS/premium.js" <<'JS'
(function(){if(window.__NDSP_V500_BOOT__)return;window.__NDSP_V500_BOOT__=true;const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));const st={lang:localStorage.getItem('ndsp_v500_lang')||'ar',sym:'BTCUSDT',cat:null,data:null};const clean=s=>String(s||'').trim().toUpperCase().replace(/[^A-Z0-9._:-]/g,'');const t=(ar,en)=>st.lang==='en'?en:ar;const route=p=>'/_premium/'+p+'.html?symbol='+encodeURIComponent(st.sym);function setSym(s){st.sym=clean(s)||'BTCUSDT';localStorage.setItem('ndsp_selected_symbol',st.sym)}function getSym(){const q=new URLSearchParams(location.search);return clean(q.get('symbol'))||clean(localStorage.getItem('ndsp_selected_symbol'))||'BTCUSDT'}async function j(u,f){try{const r=await fetch(u,{cache:'no-store'});if(r.ok)return await r.json()}catch(e){}return f}function nav(){const a=[['asset-selector','اختيار الأصل','Asset'],['decision-center','مركز القرار','Center'],['decision-radar','الرادار','Radar'],['nmp','NMP','NMP'],['decision-guide','الدليل','Guide'],['completed-decisions','المكتملة','Completed']];const p=document.body.dataset.page||'index';return a.map(x=>`<a class="${p===x[0]?'on':''}" href="${route(x[0])}">${t(x[1],x[2])}</a>`).join('')}function shell(ar,en,subar,suben,body,primary='decision-center'){document.body.dir=st.lang==='ar'?'rtl':'ltr';document.body.innerHTML=`<header class="top"><div class="shell topin"><a class="brand" href="/_premium/index.html?symbol=${st.sym}"><span class="logo">N</span><span>NDSP<small>${t('غرفة دعم القرار','Decision Support Room')}</small></span></a><nav class="nav">${nav()}</nav><div class="lang"><button data-l="ar" class="${st.lang==='ar'?'on':''}">AR</button><button data-l="en" class="${st.lang==='en'?'on':''}">EN</button></div></div></header><main class="shell"><section class="hero"><div class="kicker"><span class="dot"></span><span>V5.0 Premium</span><span class="pill">${st.sym}</span></div><h1>${t(ar,en)}</h1><p>${t(subar,suben)}</p><div class="actions"><a class="btn" href="${route(primary)}">${t('فتح مركز القرار','Open Decision Center')}</a><a class="btn secondary" href="${route('asset-selector')}">${t('تغيير الأصل','Change Asset')}</a><span class="pill">${t('ليست توصية مالية ولا أمر تنفيذ','Not financial advice or execution order')}</span></div></section>${body}<footer class="footer">${t('NDSP يبني فهمًا منظمًا ولا يصدر أوامر تنفيذ.','NDSP builds structured understanding and does not issue execution orders.')}</footer></main>`;$$('.lang button').forEach(b=>b.onclick=()=>{localStorage.setItem('ndsp_v500_lang',b.dataset.l);st.lang=b.dataset.l;render()})}function assetObj(){for(const m of(st.cat?.markets||[]))for(const a of(m.assets||[]))if(a[0]===st.sym)return{sym:a[0],ar:a[1],en:a[2],m};return null}function read(){const d=st.data||{},sc=d.scenario||{},ins=d.instrument||{};let item=null;if(Array.isArray(d.items))item=d.items.find(x=>clean(x.symbol)===st.sym)||d.items[0];const q=Number(item?.decision_quality||d.decision_quality||72),risk=Number(item?.risk_score||item?.risk||38),devil=Number(item?.devil_advocate_score||item?.devil_advocate||34);let cls='warn',label=t('تحت المتابعة','Under monitoring');if(risk>=66||devil>=66){cls='bad';label=t('موقوف','Blocked')}else if(q>=85&&risk<=40&&devil<=40){cls='ok';label=t('مكتمل','Completed')}else if(q>=80&&risk<=55&&devil<=55){cls='warn';label=t('مكتمل بحذر','Ready with caution')}return{q,risk,devil,cls,label,price:ins.live_price??item?.price??item?.live_price??'—',dir:sc.scenario_directional_context||item?.directional_context||t('غير مؤكد','Unclear'),act:sc.scenario_activation_level||item?.activation_level||'—',arr:sc.scenario_arrival_level||item?.arrival_level||'—',rev:sc.scenario_review_zone||item?.review_zone||'—',inv:sc.scenario_invalidation_level||item?.invalidation_level||'—',nmp:sc.nmp||item?.nmp||t('تحقق إضافي','Additional validation'),coh:item?.reading_cohesion||68,horizon:item?.horizon_strength||62,refs:item?.reference_levels_score||78}}function metric(ar,en,v,note=''){v=Math.max(0,Math.min(100,Number(v)||0));return`<div class="metric"><div class="mrow"><b>${t(ar,en)}</b><div class="bar"><i style="width:${v}%"></i></div><strong>${v}</strong></div>${note?`<small>${note}</small>`:''}</div>`}function assets(){const blocks=(st.cat?.markets||[]).map(m=>`<section class="market"><h2>${t(m.ar,m.en)}</h2><div class="assets">${m.assets.map(a=>`<button class="asset" data-s="${a[0]}"><b>${a[0]}</b><span>${t(a[1],a[2])}</span><small>${t('متابعة منظمة ضمن غرفة القرار','Structured monitoring inside the decision room')}</small></button>`).join('')}</div></section>`).join('');shell('اختيار أصل يليق بغرفة قرار','Asset Selection for a Decision Room','ابدأ من أصل واضح، ثم انتقل إلى مركز القرار والرادار.','Start with a clear asset, then move to the decision center and radar.',`<section class="card">${blocks}</section>`);$$('.asset').forEach(b=>b.onclick=()=>{setSym(b.dataset.s);location.href=route('decision-center')})}function center(){const r=read(),a=assetObj();shell('مركز القرار التنفيذي','Executive Decision Center','الخلاصة أولًا، ثم المخاطر، المستويات، والرادار.','Summary first, then risk, levels, and radar.',`<section class="grid"><div class="card span8"><h2>${t('الخلاصة النهائية','Final Summary')}</h2><p>${t('قراءة دعم قرار للأصل المختار. الهدف هو الفهم وليس إصدار أمر.','Decision-support reading for the selected asset. The goal is understanding, not issuing an order.')}</p><span class="chip ${r.cls}">${r.label}</span><p class="note">${t('المستويات مناطق متابعة وليست أوامر تنفيذ.','Levels are monitoring zones, not execution orders.')}</p><div class="actions"><a class="btn" href="${route('decision-radar')}">${t('عرض الرادار','View Radar')}</a><a class="btn secondary" href="${route('nmp')}">${t('فحص NMP','Check NMP')}</a></div></div><div class="card span4"><div class="label">${t('الأصل والسعر','Asset & Price')}</div><div class="value">${st.sym}</div><p>${a?t(a.ar,a.en):t('غير مدعوم حاليًا','Currently unsupported')}</p><span class="pill">${r.price}</span></div><div class="card span3"><div class="label">${t('الجاهزية','Readiness')}</div><div class="value">${r.q}</div></div><div class="card span3"><div class="label">${t('المخاطر','Risk')}</div><div class="value">${r.risk}</div><p>${t('الأقل أفضل','Lower is better')}</p></div><div class="card span3"><div class="label">${t('محامي الشيطان','Devil’s Advocate')}</div><div class="value">${r.devil}</div><p>${t('الأقل أفضل','Lower is better')}</p></div><div class="card span3"><div class="label">${t('السياق','Context')}</div><div class="value" style="font-size:28px">${r.dir}</div></div><div class="card"><h2>${t('المستويات المرجعية','Reference Levels')}</h2><div class="grid">${[['تفعيل','Activation',r.act],['وصول','Arrival',r.arr],['مراجعة','Review',r.rev],['إلغاء','Invalidation',r.inv]].map(x=>`<div class="card span3"><div class="label">${t(x[0],x[1])}</div><div class="value" style="font-size:28px">${x[2]}</div></div>`).join('')}</div></div></section>`)}function radar(){const r=read();shell('رادار قرار فاخر','Premium Decision Radar','مساعد بصري سريع لا يلغي الخلاصة أو تفسير المخاطر.','A fast visual assistant that does not replace summary or risk explanation.',`<section class="grid"><div class="card span6"><div class="radar"><div class="sweep"></div><div class="core"><div><b>${st.sym}</b><span>${r.label}</span></div></div></div></div><div class="card span6"><h2>${t('محاور القراءة','Reading Axes')}</h2>${metric('الجاهزية النهائية','Final readiness',r.q)}${metric('تماسك القراءة','Reading cohesion',r.coh)}${metric('المستويات المرجعية','Reference levels',r.refs)}${metric('NMP','NMP',70)}${metric('قوة الأفق','Horizon strength',r.horizon)}${metric('المخاطر','Risk',100-r.risk,t('عكسي: الأقل أفضل','Inverse: lower is better'))}${metric('محامي الشيطان','Devil’s Advocate',100-r.devil,t('عكسي: الأقل أفضل','Inverse: lower is better'))}</div></section>`)}function nmp(){const r=read();shell('نقطة التقاء نواف','Nawaf Meet Point','منطقة تحقق إضافية عند توفر البيانات. لا يتم اختراعها.','Additional validation zone when data is available. It is not invented.',`<section class="grid"><div class="card span6"><h2>NMP</h2><div class="value">${r.nmp}</div><p>${t('إذا لم تتوفر بيانات كافية تظهر المنصة ذلك بوضوح.','If enough data is unavailable, the platform says so clearly.')}</p></div><div class="card span6"><h2>${t('السياق','Context')}</h2>${metric('الجاهزية','Readiness',r.q)}${metric('قوة الأفق','Horizon strength',r.horizon)}</div></section>`)}function guide(){shell('دليل فهم القرار','Decision Guide','ابدأ بالخلاصة ثم المخاطر ثم المستويات والرادار.','Start with summary, then risk, then levels and radar.',`<section class="grid"><div class="card span6"><h2>${t('للمستخدم العادي','For normal users')}</h2><p>${t('ركز على الحالة النهائية، المخاطر، أهم مستوى، وهل NMP متاح.','Focus on final state, risk, key level, and whether NMP is available.')}</p></div><div class="card span6"><h2>${t('للمحلل المتقدم','For advanced analysts')}</h2><p>${t('افهم تماسك القراءة وقوة الأفق ومحامي الشيطان.','Understand cohesion, horizon strength, and Devil’s Advocate.')}</p></div></section>`)}function completed(){shell('القراءات المكتملة','Completed Readings','سجل قراءات مكتملة وليست صفقات.','Completed readings log, not trades.',`<section class="card"><h2>${t('سجل Preview','Preview Log')}</h2><p>${t('يرتبط السجل النهائي بعد اعتماد التصميم.','Final log binding comes after design approval.')}</p><div class="value">${st.sym}</div></section>`)}function home(){shell('غرفة قرار تستحق الثقة','A Decision Room Worth Trusting','نسخة V5.0 تركز على الفخامة المؤسسية ووضوح الخلاصة والرادار.','V5.0 focuses on institutional premium feel, clarity, and radar.',`<section class="grid"><div class="card span4"><div class="label">${t('البنية','Architecture')}</div><div class="value">1</div><p>${t('Runtime واحد','One runtime')}</p></div><div class="card span4"><div class="label">${t('التصميم','Design')}</div><div class="value">V5</div><p>${t('فاخر ومؤسسي','Premium institutional')}</p></div><div class="card span4"><div class="label">${t('الهوية','Identity')}</div><div class="value">NDSP</div><p>${t('دعم قرار فقط','Decision support only')}</p></div></section>`,'asset-selector')}async function render(){setSym(getSym());st.cat=await j('/_premium/data/assets.json',{markets:[]});st.data=await j('/api/decision/quality-live?symbol='+encodeURIComponent(st.sym),await j('/data/command-center-real.json',{}));({index:home,'asset-selector':assets,'decision-center':center,'decision-radar':radar,nmp:nmp,'decision-guide':guide,'completed-decisions':completed}[document.body.dataset.page||'index']||home)()}document.addEventListener('DOMContentLoaded',render)})();
JS
make_page(){ p="$1"; title="$2"; cat > "$PREMIUM/$p.html" <<HTML
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#030304"><title>$title — NDSP V5</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="/_premium/assets/premium.css?v=$TS"></head><body data-page="$p"><script src="/_premium/assets/premium.js?v=$TS" defer></script></body></html>
HTML
}
make_page index NDSP
make_page asset-selector "اختيار الأصل"
make_page decision-center "مركز القرار"
make_page decision-radar "رادار القرار"
make_page nmp NMP
make_page decision-guide "دليل القرار"
make_page completed-decisions "القراءات المكتملة"
log ""
log "== VERIFY FILES =="
for f in "$PREMIUM/index.html" "$PREMIUM/asset-selector.html" "$PREMIUM/decision-center.html" "$PREMIUM/decision-radar.html" "$PREMIUM/nmp.html" "$ASSETS/premium.css" "$ASSETS/premium.js" "$DATA/assets.json"; do [ -f "$f" ] && log "FILE_OK=$f SIZE=$(wc -c < "$f")" || log "FILE_MISSING=$f"; done
log ""
log "== HTTP =="
for url in "https://my.ndsp.app/_premium/index.html" "https://my.ndsp.app/_premium/asset-selector.html?symbol=BTCUSDT" "https://my.ndsp.app/_premium/decision-center.html?symbol=BTCUSDT" "https://my.ndsp.app/_premium/decision-radar.html?symbol=BTCUSDT" "https://my.ndsp.app/_premium/nmp.html?symbol=BTCUSDT" "https://my.ndsp.app/_premium/decision-center.html?symbol=CORN" "https://my.ndsp.app/login" "https://my.ndsp.app/register"; do out="/tmp/v500_check.html"; sep="?"; echo "$url"|grep -q '?'&&sep="&"; code="$(curl -skL --connect-timeout 8 --max-time 20 -o "$out" -w "%{http_code}" "$url${sep}v=$TS"||echo 000)"; size="$(wc -c < "$out" 2>/dev/null||echo 0)"; prem="$(grep -Ec '/_premium/assets/(premium.css|premium.js)' "$out"||true)"; old="$(grep -Eoc 'ndsp-v48|ndsp-v49|ndsp-mobile|index-[A-Za-z0-9]' "$out"||true)"; auth="$(grep -c 'ndsp-v476-auth-api-binding.js' "$out"||true)"; obj="$(grep -c '\[object Object\]' "$out"||true)"; log "$url => HTTP=$code SIZE=$size PREMIUM_REFS=$prem OLD_PATCH=$old AUTH_MARKER=$auth OBJECT_TEXT=$obj"; done
cp -a "$PREMIUM" "$CHECKPOINT/_premium"
ROLLBACK="/tmp/ndsp_rollback_v500_premium_bootstrap_$TS.sh"
cat > "$ROLLBACK" <<EOF
#!/usr/bin/env bash
set -euo pipefail
if [ -d "$BACKUP/_premium.before_v500" ]; then rm -rf "$PREMIUM"; cp -a "$BACKUP/_premium.before_v500" "$PREMIUM"; else rm -rf "$PREMIUM"; fi
nginx -t && systemctl reload nginx
echo ROLLBACK_OK
EOF
chmod +x "$ROLLBACK"
log ""
log "FINAL_STATUS=NDSP_V500_PREMIUM_BOOTSTRAP_DONE"
log "URL_PREMIUM=https://my.ndsp.app/_premium/asset-selector.html?symbol=BTCUSDT&v=$TS"
log "URL_RADAR=https://my.ndsp.app/_premium/decision-radar.html?symbol=BTCUSDT&v=$TS"
log "URL_CORN=https://my.ndsp.app/_premium/decision-center.html?symbol=CORN&v=$TS"
log "CHECKPOINT=$CHECKPOINT"
log "ROLLBACK=$ROLLBACK"
log "REPORT=$REPORT"
